// FUNCTIONS //

/**
* Tests whether two values are approximately equal.
*
* @private
* @param {Object} t - test object
* @param {number} actual - actual value
* @param {number} expected - expected value
* @param {string} msg - message
*/
function isApprox( t, actual, expected, msg ) {
	var delta;
	var tol;

	if ( actual === expected ) {
		t.strictEqual( actual, expected, msg );
	} else {
		delta = abs( actual - expected );
		tol = 20.0 * EPS * abs( expected );
		t.ok( delta <= tol, msg + '. Expected: ' + expected + '. Actual: ' + actual + '. Delta: ' + delta + '. Tol: ' + tol + '.' );
	}
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlansy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 6', function test( t ) {
	t.strictEqual( dlansy.length, 6, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided an invalid first argument', function test( t ) {
	var values;
	var A;
	var i;

	values = [
		'foo',
		'bar',
		'beep',
		'boop'
	];

	A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlansy( value, 'M', 'upper', 2, A, 2 );
		};
	}
});

