tape( 'the function throws an error if provided an invalid LDA (row-major)', function test( t ) {
	var A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );

	t.throws( badValue, RangeError, 'throws a range error' );
	t.end();

	function badValue() {
		// N = 2, row-major requires LDA >= max(1, N) = 2
		dlansy( 'row-major', 'M', 'upper', 2, A, 1 );
	}
});

tape( 'the function returns 0 when N is 0', function test( t ) {
	var A = new Float64Array( [ 1.0 ] );
	var v;

	v = dlansy( 'row-major', 'M', 'upper', 0, A, 1 );
	t.strictEqual( v, 0.0, 'returns expected value' );

	v = dlansy( 'row-major', '1', 'lower', 0, A, 1 );
	t.strictEqual( v, 0.0, 'returns expected value' );

	v = dlansy( 'row-major', 'F', 'upper', 0, A, 1 );
	t.strictEqual( v, 0.0, 'returns expected value' );

	t.end();
});

tape( 'the function computes the max norm (row-major, upper)', function test( t ) {
	var data = MAX_NORM_ROW_MAJOR_UPPER;
	var v = dlansy( data.order, data.norm, data.uplo, data.N, new Float64Array( data.A ), data.LDA );
	t.strictEqual( v, data.expected, 'returns expected value' );
	t.end();
});

