tape( 'the function computes the infinity norm (symmetric: normI == norm1)', function test( t ) {
	var one;
	var A;
	var v;

	// For symmetric matrices, infinity norm equals one norm:
	A = new Float64Array( ONE_NORM_ROW_MAJOR_UPPER.A );
	one = dlansy( 'row-major', '1', 'upper', ONE_NORM_ROW_MAJOR_UPPER.N, A, ONE_NORM_ROW_MAJOR_UPPER.LDA );
	v = dlansy( 'row-major', 'I', 'upper', ONE_NORM_ROW_MAJOR_UPPER.N, A, ONE_NORM_ROW_MAJOR_UPPER.LDA );
	t.strictEqual( v, one, 'infinity norm equals one norm (upper)' );

	A = new Float64Array( ONE_NORM_ROW_MAJOR_LOWER.A );
	one = dlansy( 'row-major', '1', 'lower', ONE_NORM_ROW_MAJOR_LOWER.N, A, ONE_NORM_ROW_MAJOR_LOWER.LDA );
	v = dlansy( 'row-major', 'I', 'lower', ONE_NORM_ROW_MAJOR_LOWER.N, A, ONE_NORM_ROW_MAJOR_LOWER.LDA );
	t.strictEqual( v, one, 'infinity norm equals one norm (lower)' );

	t.end();
});

