tape( 'the function supports norm character aliases', function test( t ) {
	var A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );
	var v;

	v = dlansy( 'row-major', 'm', 'upper', 2, A, 2 );
	t.strictEqual( v, 5.0, 'returns expected value for lowercase m' );

	v = dlansy( 'row-major', 'o', 'upper', 2, A, 2 );
	t.strictEqual( v, 7.0, 'returns expected value for lowercase o' );

	v = dlansy( 'row-major', 'i', 'upper', 2, A, 2 );
	t.strictEqual( v, 7.0, 'returns expected value for lowercase i' );

	v = dlansy( 'row-major', 'O', 'upper', 2, A, 2 );
	t.strictEqual( v, 7.0, 'returns expected value for O' );

	v = dlansy( 'row-major', 'f', 'upper', 2, A, 2 );
	isApprox( t, v, dlansy( 'row-major', 'F', 'upper', 2, A, 2 ), 'returns expected value for lowercase f' );

	v = dlansy( 'row-major', 'E', 'upper', 2, A, 2 );
	isApprox( t, v, dlansy( 'row-major', 'F', 'upper', 2, A, 2 ), 'returns expected value for E' );

	v = dlansy( 'row-major', 'e', 'upper', 2, A, 2 );
	isApprox( t, v, dlansy( 'row-major', 'F', 'upper', 2, A, 2 ), 'returns expected value for lowercase e' );

	t.end();
});

tape( 'the function handles N=1', function test( t ) {
	var A = new Float64Array( [ 7.0 ] );
	var v;

	v = dlansy( 'row-major', 'M', 'upper', 1, A, 1 );
	t.strictEqual( v, 7.0, 'returns expected value for M norm' );

	v = dlansy( 'row-major', '1', 'upper', 1, A, 1 );
	t.strictEqual( v, 7.0, 'returns expected value for one norm' );

	v = dlansy( 'row-major', 'I', 'lower', 1, A, 1 );
	t.strictEqual( v, 7.0, 'returns expected value for infinity norm' );

	v = dlansy( 'row-major', 'F', 'upper', 1, A, 1 );
	isApprox( t, v, 7.0, 'returns expected value for Frobenius norm' );

	t.end();
});
